    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '301: "Hypermagnesemia" (elevated magnesium) on ECG typically mirrors the changes seen in:', '["Hyperkalemia", "Hypocalcemia", "Hypokalemia", "Hypercalcemia"]', 0, 'Severe hypermagnesemia can cause PR and QRS prolongation and even heart block, similar to hyperkalemia.'),
    (v_topic_id, '302: "Hypomagnesemia" is clinically important because it often co-exists with, and makes it harder to treat, which other electrolyte abnormality?', '["Hypernatremia", "Hypokalemia", "Hypercalcemia", "Hyperchloremia"]', 1, 'Hypomagnesemia impairs the kidney''s ability to conserve potassium; therefore, hypokalemia is often refractory to treatment until magnesium is replaced.'),
    (v_topic_id, '303: In "Digitalis toxicity", which of the following is the most specific arrhythmia?', '["Atrial Fibrillation", "Bidirectional Ventricular Tachycardia", "Sinus Bradycardia", "LBBB"]', 1, 'While rare, bidirectional VT is nearly pathognomonic for severe digoxin toxicity.'),
    (v_topic_id, '304: A "Pacemaker-induced QRS complex" most closely resembles which bundle branch block pattern?', '["Right Bundle Branch Block (RBBB)", "Left Bundle Branch Block (LBBB)", "Bifascicular block", "Trifascicular block"]', 1, 'Because most pacemaker leads are placed in the right ventricle, the depolarization spreads from right to left, mimicking a LBBB pattern.'),
    (v_topic_id, '305: "Failure to Sense" by a pacemaker means:', '["The pacemaker fails to deliver a shock", "The pacemaker fires inappropriately because it doesn''t see the heart''s own intrinsic electrical activity", "The battery is dead", "The heart is too fast"]', 1, 'This results in pacemaker spikes occurring where they shouldn''t, such as on top of a native T-wave (a dangerous R-on-T risk).'),
    (v_topic_id, '306: In a patient with an ICD (Implantable Cardioverter Defibrillator), what is the function of the "antitachycardia pacing" (ATP) feature?', '["To shock the heart immediately", "To pace the heart slightly faster than the VT to \"break\" the re-entrant circuit and return it to sinus rhythm", "To slow the heart down", "To record the rhythm only"]', 1, 'ATP can often terminate stable VT without the need for a painful shock.'),
    (v_topic_id, '307: "Brugada Syndrome" is most often caused by a mutation in which ion channel gene?', '["SCN5A (Sodium channel)", "KCNH2 (Potassium channel)", "CACNA1C (Calcium channel)", "RYR2"]', 0, 'Most identified mutations in Brugada affect the cardiac sodium channel.'),
    (v_topic_id, '308: Which of the following "provocation tests" can be used in the hospital to unmask a suspected Brugada ECG pattern?', '["Adenosine", "Sodium channel blockers (e.g., Flecainide or Procainamide)", "Beta-blockers", "Atropine"]', 1, 'Blocking sodium channels further exaggerates the Brugada pattern, confirming the diagnosis.'),
    (v_topic_id, '309: "Romano-Ward Syndrome" is the most common form of congenital Long QT Syndrome. It is inherited in which fashion?', '["Autosomal dominant", "Autosomal recessive", "X-linked", "Mitochondrial"]', 0, 'Romano-Ward is AD and is not associated with deafness (unlike Jervell and Lange-Nielsen).'),
    (v_topic_id, '310: "Jervell and Lange-Nielsen Syndrome" is a congenital Long QT Syndrome associated with which other clinical finding?', '["Polydactyly", "Sensorineural deafness", "Cataracts", "Cleft palate"]', 1, 'This is an autosomal recessive condition combining Long QT with congenital deafness.'),
    (v_topic_id, '311: "Catecholaminergic Polymorphic Ventricular Tachycardia" (CPVT) is a cause of sudden death in children triggered by:', '["Sleep", "Exercise or emotional stress", "Eating", "Coughing"]', 1, 'CPVT involves abnormal calcium handling (often RyR2 mutations) triggered by surges in adrenaline.'),
    (v_topic_id, '312: "Arrhythmogenic Right Ventricular Cardiomyopathy" (ARVC) is characterized by the replacement of RV myocardium with fibrofatty tissue. Its hallmark ECG finding in V1-V3 is:', '["Tall R-waves", "The Epsilon wave (a small notch at the end of the QRS)", "ST elevation", "Short QT"]', 1, 'The epsilon wave is highly specific for ARVC.'),
    (v_topic_id, '313: In children, the "Normal Heart Rate" is:', '["The same as adults", "Faster (often > 100 bpm in infants)", "Slower", "Always irregular"]', 1, 'Resting heart rate gradually decreases from birth (~140 bpm) to adolescence.'),
    (v_topic_id, '314: In a newborn, the ECG axis is normally:', '["Left-deviated", "Right-deviated", "Vertical", "Horizontal"]', 1, 'Neonates have right ventricular dominance because of the fetal circulation pattern, leading to a physiological RAD.'),
    (v_topic_id, '315: By what age does the ECG axis and R-wave progression in a child typically resemble that of an adult?', '["6 months", "1 year", "3 years", "Adolescence (12-15 years)"]', 3, 'The transition from RV dominance to LV dominance happens gradually during childhood.'),
    (v_topic_id, '316: A "Congenital Complete Heart Block" in a newborn is most commonly associated with which maternal condition?', '["Diabetes", "Systemic Lupus Erythematosus (SLE) or Sj\u00f6gren''s syndrome", "Hypertension", "Alcoholism"]', 1, 'Anti-Ro/SSA and anti-La/SSB antibodies can cross the placenta and damage the fetal conduction system.'),
    (v_topic_id, '317: "Ebstein''s Anomaly" (apical displacement of the tricuspid valve) is frequently associated with which ECG finding?', '["LBBB", "WPW syndrome (accessory pathways)", "Short QT", "Inverted P-waves"]', 1, 'Up to 20% of patients with Ebstein''s have accessory pathways.'),
    (v_topic_id, '318: "Ostium secundum Atrial Septal Defect" (ASD) is classically associated with which ECG finding?', '["LBBB", "Incomplete RBBB and RAD", "LAD", "Short PR interval"]', 1, 'The volume overload of the right heart in ASD leads to RAE, RVH, and RBBB patterns.'),
    (v_topic_id, '319: "Ostium primum Atrial Septal Defect" (associated with Down Syndrome) is distinguished from secundum ASD by the presence of:', '["Right Axis Deviation", "Left Axis Deviation", "Short QT", "Tall T-waves"]', 1, 'The LAD in primum ASD is a key diagnostic differentiator.'),
    (v_topic_id, '320: "Hypertrophic Cardiomyopathy" (HCM) in young athletes often shows which finding on ECG?', '["Low voltage", "Deep, narrow \"dagger-like\" Q-waves in lateral and inferior leads", "LBBB", "Short PR interval"]', 1, 'These dagger Q-waves represent septal hypertrophy.'),
    (v_topic_id, '321: "Athlete''s Heart" can show which "normal" ECG variations?', '["Sinus bradycardia and 1st-degree AV block", "Voltage criteria for LVH", "Early repolarization", "All of the above"]', 3, 'In highly trained athletes, these findings are usually physiological adaptations and not pathology.'),
    (v_topic_id, '322: "Atrial Fibrillation" is the most common arrhythmia in which age group?', '["Neonates", "Adolescents", "Young adults", "The elderly (> 65 years)"]', 3, 'The prevalence of AFib increases significantly with age.'),
    (v_topic_id, '323: "Ventricular Tachycardia" in a young person with a structurally normal heart and a "Left Bundle Branch Block" pattern with an "Inferior Axis" suggests:', '["Acute MI", "RV Outflow Tract (RVOT) Tachycardia", "Brugada syndrome", "Long QT"]', 1, 'RVOT is a common, usually benign form of idiopathic VT.'),
    (v_topic_id, '324: "Commotio Cordis" refers to sudden cardiac death caused by:', '["A blunt blow to the chest during the vulnerable phase of repolarization (T-wave)", "A heart attack", "Congenital heart disease", "Electrocution"]', 0, 'This is a rare but tragic event, often seen in youth baseball or hockey.'),
    (v_topic_id, '325: Why is "Sotalol" unique among beta-blockers regarding the ECG?', '["It shortens the QT", "It has Class III properties and can prolong the QT interval", "It narrows the QRS", "It causes ST elevation"]', 1, 'Unlike most beta-blockers, Sotalol can trigger Torsades de Pointes.'),
    (v_topic_id, '326: "Amiodarone" prolongs the QT interval but is unique because it:', '["Frequently causes Torsades de Pointes", "Rarely causes Torsades de Pointes despite QT prolongation", "Shortens the PR interval", "Narrows the QRS"]', 1, 'Amiodarone is generally considered "safe" regarding Torsades risk compared to other Class III drugs.'),
    (v_topic_id, '327: "Tricyclic Antidepressant" (TCA) toxicity causes QRS widening. What is the pharmacological reason for this?', '["Potassium channel blockade", "Fast Sodium channel blockade", "Calcium channel blockade", "Beta-receptor blockade"]', 1, 'TCAs act like Class Ia antiarrhythmics in high doses, slowing the initial phase of the action potential.'),
    (v_topic_id, '328: What is the primary treatment for QRS widening in TCA overdose?', '["Atropine", "Intravenous Sodium Bicarbonate", "Dialysis", "Cardioversion"]', 1, 'Bicarbonate increases the extracellular sodium concentration and pH, favoring the inactive state of the drug-receptor complex.'),
    (v_topic_id, '329: "Hyperkalemia" can mimic which other ECG pattern?', '["Brugada pattern", "STEMI", "Bundle Branch Block", "All of the above"]', 3, 'Severe hyperkalemia is the "Great Imitator" and should always be considered in the differential of a bizarre ECG.'),
    (v_topic_id, '330: "Hypomagnesemia" increases the risk of which drug-induced toxicity?', '["Digoxin", "Lithium", "Aspirin", "Penicillin"]', 0, 'Low magnesium increases the sensitivity of the heart to digoxin.'),
    (v_topic_id, '331: The "ST-T segment" in children often shows T-wave inversions in V1-V3. This is called:', '["Ischemia", "Juvenile T-wave pattern", "Right heart strain", "RBBB"]', 1, 'This is a normal finding that usually resolves by late adolescence.'),
    (v_topic_id, '332: A "delta wave" on an ECG is evidence of pre-excitation. What does "pre-excitation" mean anatomically?', '["The ventricles contract before the atria", "An impulse reaches the ventricles via an accessory pathway faster than it travels through the AV node", "The SA node fires too fast", "The heart is excited twice"]', 1, 'This bypasses the normal delay in the AV node.'),
    (v_topic_id, '333: "Orthodromic" AVRT (Atrioventricular Re-entrant Tachycardia) is characterized by:', '["A wide QRS complex", "A narrow QRS complex (conduction goes DOWN the AV node and UP the accessory pathway)", "A delta wave", "No P-waves"]', 1, 'This is the most common form of tachycardia in WPW patients.'),
    (v_topic_id, '334: "Antidromic" AVRT is characterized by:', '["A narrow QRS complex", "A wide QRS complex (conduction goes DOWN the accessory pathway and UP the AV node)", "A very slow rate", "Short QT"]', 1, 'Because the ventricles are depolarized entirely via the accessory pathway, the QRS is wide and bizarre.'),
    (v_topic_id, '335: "Atrioventricular Nodal Re-entrant Tachycardia" (AVNRT) usually involves two pathways within the AV node. They are:', '["Fast and Slow pathways", "Left and Right pathways", "Anterior and Posterior pathways", "Primary and Secondary pathways"]', 0, 'The re-entrant loop forms between these two functional pathways.'),
    (v_topic_id, '336: A "P-wave" that is buried in the QRS complex during a narrow-complex tachycardia is highly suggestive of:', '["Sinus Tachycardia", "AVNRT (Typical)", "Atrial Flutter", "AVRT"]', 1, 'In typical (slow-fast) AVNRT, the atria and ventricles are activated nearly simultaneously.'),
    (v_topic_id, '337: "Ectopic Atrial Tachycardia" (EAT) is characterized by:', '["A sawtooth baseline", "A regular tachycardia with P-waves that have a different morphology and axis than the sinus P-wave", "Irregularity", "Wide QRS"]', 1, 'EAT comes from a single ectopic spot in the atria.'),
    (v_topic_id, '338: "Pseudo-block" in a child can be caused by:', '["Atrial enlargement", "The small size of the chest wall placing the leads closer to the heart", "Normal variation", "Low voltage"]', 1, 'The proximity of the heart to the chest wall can make normal signals look excessively large.'),
    (v_topic_id, '339: "ST depression" in a patient with Digitalis is called "digitalis effect." When does it become "digitalis toxicity"?', '["When the ST segment is scooped", "When it is accompanied by arrhythmias (e.g., PVCs, heart block, or tachycardias)", "When the PR interval is 0.18s", "Always"]', 1, 'ST segment "scooping" alone is not a sign of toxicity; it only indicates the presence of the drug.'),
    (v_topic_id, '340: A "Long PR interval" (> 0.20s) that is constant beat-to-beat is:', '["First-degree AV block", "Wenckebach", "Mobitz II", "Normal"]', 0, 'Every P-wave is conducted, just delayed.'),
    (v_topic_id, '341: "Electrical Alternans" in a patient with a very fast heart rate (SVT) is often:', '["A sign of tamponade", "A normal finding due to rate-related aberrancy", "A sign of a bundle branch block", "A sign of MI"]', 1, 'At very high rates, the conduction system may not fully recover between beats, causing alternating amplitudes.'),
    (v_topic_id, '342: "Bidirectional VT" is most commonly associated with which genetic condition (besides digitalis toxicity)?', '["Brugada syndrome", "Catecholaminergic Polymorphic VT (CPVT)", "Long QT Syndrome", "WPW"]', 1, 'CPVT is a key differential for bidirectional VT.'),
    (v_topic_id, '343: In "Atrial Flutter", the "Sawtooth" waves are usually inverted in which leads?', '["I, aVL", "II, III, aVF", "V1, V2", "aVR"]', 1, 'Typical (counter-clockwise) flutter shows negative sawtooth waves in the inferior leads.'),
    (v_topic_id, '344: "Counter-clockwise Atrial Flutter" involves a re-entrant circuit around which anatomical structure?', '["The Mitral Valve", "The Tricuspid Valve (Cavo-tricuspid isthmus)", "The Pulmonary Veins", "The Aorta"]', 1, 'Typical flutter is nearly always isthmus-dependent.'),
    (v_topic_id, '345: "Clockwise Atrial Flutter" (Reverse Typical) shows which finding in the inferior leads?', '["Inverted sawtooth waves", "Positive sawtooth waves", "No waves", "Wide QRS"]', 1, 'The direction of the circuit flips the polarity of the flutter waves.'),
    (v_topic_id, '346: A "U-wave" that is larger than the T-wave is most commonly seen in:', '["Hyperkalemia", "Severe Hypokalemia", "Hypercalcemia", "Normal heart"]', 1, 'This is a classic sign of severe potassium depletion.'),
    (v_topic_id, '347: "Hyperacute T-waves" can sometimes be mistaken for:', '["Inverted T-waves", "Early repolarization or Hyperkalemia", "ST depression", "Pathological Q-waves"]', 1, 'Differentiating these requires careful attention to the T-wave shape and clinical context.'),
    (v_topic_id, '348: "Pathological Q-waves" in the septal leads (V1-V2) suggest an old MI in which territory?', '["Inferior", "Lateral", "Septal", "Posterior"]', 2, 'Q-waves indicate a previous transmural infarction in that area.'),
    (v_topic_id, '349: A patient with "Dextrocardia" will have a QRS axis that is typically:', '["Normal", "Markedly right-deviated", "Left-deviated", "Vertical"]', 1, 'The electrical activity is oriented toward the right chest.'),
    (v_topic_id, '350: "ECG Interpretation" is a vital skill, but the most important rule is to always:', '["Memorize every criterion", "Correlate the ECG findings with the patient''s clinical presentation", "Trust the computer interpretation", "Only look at Lead II"]', 1, 'The ECG is a tool that must be used in conjunction with the history and physical exam to make an accurate diagnosis.');
